package com.transportlogistics.app.fuel.infrastructure.adapters.out.persistence;

import com.transportlogistics.app.support.PostgreSqlIntegrationTest;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.dao.DataAccessException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.jdbc.core.simple.JdbcClient;
import java.time.OffsetDateTime;
import java.util.UUID;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class FuelExceptionPostgreSqlAcceptanceTest extends PostgreSqlIntegrationTest {
 @Autowired JdbcClient jdbc;
 @Test void v67OwnsSevenTenantIndexedTablesFivePermissionsAndFuelOperationsIntake(){assertThat(jdbc.sql("select version from flyway_schema_history where success order by installed_rank desc limit 1").query(String.class).single()).isEqualTo("76");assertThat(jdbc.sql("select count(*) from information_schema.tables where table_schema='public' and table_name like 'fuel_exception_%'").query(Integer.class).single()).isEqualTo(7);assertThat(jdbc.sql("select count(*) from app_permission where code like 'FUEL_EXCEPTION_%' and active").query(Integer.class).single()).isEqualTo(5);assertThat(jdbc.sql("select check_clause from information_schema.check_constraints where constraint_name='ck_operational_exception_source_module'").query(String.class).single()).contains("FUEL");assertThat(jdbc.sql("select count(*) from information_schema.columns where table_name='fuel_exception_correction' and column_name in ('owner_module','owner_type','requested_command_type','safe_request_evidence','before_snapshot_hash','request_reason','requested_at','execution_state','idempotency_key') and is_nullable='NO'").query(Integer.class).single()).isEqualTo(9);assertThat(jdbc.sql("select character_maximum_length from information_schema.columns where table_name='fuel_exception_note' and column_name='note'").query(Integer.class).single()).isEqualTo(2000);assertThat(jdbc.sql("select count(*) from pg_indexes where tablename='fuel_exception_operations_handoff' and indexdef like '%(tenant_id, handoff_event_id)%'").query(Integer.class).single()).isGreaterThanOrEqualTo(1);}
 @Test void activeSourceAndTenantConsistentChildrenAreEnforced(){UUID t=UUID.randomUUID(),source=UUID.randomUUID(),first=insertCase(t,source,"OPEN");assertThatThrownBy(()->insertCase(t,source,"UNDER_REVIEW")).isInstanceOf(DataIntegrityViolationException.class);jdbc.sql("update fuel_exception_case set lifecycle='RESOLVED' where id=:id").param("id",first).update();UUID active=insertCase(t,source,"OPEN");assertThatThrownBy(()->jdbc.sql("insert into fuel_exception_note(id,tenant_id,exception_id,note,added_by,created_at) values(:id,:other,:x,'review required',:actor,:now)").param("id",UUID.randomUUID()).param("other",UUID.randomUUID()).param("x",first).param("actor",UUID.randomUUID()).param("now",OffsetDateTime.now()).update()).isInstanceOf(DataIntegrityViolationException.class);UUID correction=insertCorrection(t,active);assertThatThrownBy(()->jdbc.sql("insert into fuel_exception_correction_attempt(attempt_id,tenant_id,correction_id,attempt_number,idempotency_key,attempted_at,attempted_by,result) values(:id,:other,:correction,1,:key,:now,:actor,'FAILED')").param("id",UUID.randomUUID()).param("other",UUID.randomUUID()).param("correction",correction).param("key",correction).param("now",OffsetDateTime.now()).param("actor",UUID.randomUUID()).update()).isInstanceOf(DataIntegrityViolationException.class);UUID attempt=UUID.randomUUID();jdbc.sql("insert into fuel_exception_correction_attempt(attempt_id,tenant_id,correction_id,attempt_number,idempotency_key,attempted_at,attempted_by,result) values(:id,:t,:correction,1,:key,:now,:actor,'FAILED')").param("id",attempt).param("t",t).param("correction",correction).param("key",correction).param("now",OffsetDateTime.now()).param("actor",UUID.randomUUID()).update();assertThatThrownBy(()->jdbc.sql("update fuel_exception_correction_attempt set result='SUCCESS' where attempt_id=:id").param("id",attempt).update()).isInstanceOf(DataAccessException.class).hasMessageContaining("Fuel exception audit rows are append-only");}
 private UUID insertCorrection(UUID tenant,UUID exception){UUID id=UUID.randomUUID(),actor=UUID.randomUUID();var now=OffsetDateTime.now();jdbc.sql("insert into fuel_exception_correction(id,tenant_id,exception_id,correction_type,owner_command,changes_financial_fact,status,requested_by,version,created_at,updated_at,owner_module,owner_type,requested_command_type,safe_request_evidence,before_snapshot_hash,request_reason,requested_at,execution_state,idempotency_key) values(:id,:t,:x,'BUNKER_STOCK_ADJUSTMENT','{\"reason\":\"review\"}',true,'AWAITING_APPROVAL',:actor,0,:now,:now,'FUEL','BUNKER_STOCK_ADJUSTMENT','BUNKER_STOCK_ADJUSTMENT','{\"reason\":\"review\"}',repeat('a',64),'review',:now,'NOT_STARTED',:id)").param("id",id).param("t",tenant).param("x",exception).param("actor",actor).param("now",now).update();return id;}
 private UUID insertCase(UUID t,UUID source,String state){UUID id=UUID.randomUUID(),actor=UUID.randomUUID();var now=OffsetDateTime.now();jdbc.sql("insert into fuel_exception_case(id,tenant_id,category,lifecycle,impact,source_type,source_id,summary,safe_metadata,occurred_at,review_required,handoff_status,created_by,version,created_at,updated_at) values(:id,:t,'SUSPECTED_FUEL_LOSS',:state,'MEDIUM','FUEL_ISSUE',:source,'Unexplained variance requires review','{}',:now,true,'NOT_REQUIRED',:actor,0,:now,:now)").param("id",id).param("t",t).param("state",state).param("source",source).param("now",now).param("actor",actor).update();return id;}
}
